<div class="card"><div class="card-header">Pedidos</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>#</th><th>Cliente</th><th>Tipo</th><th>Status</th><th>Pagamento</th><th>Total</th><th>Ações</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?= $o['id'] ?></td><td><?= htmlspecialchars($o['customer_name'] ?? 'Consumidor') ?></td><td><span class="badge text-bg-info"><?= htmlspecialchars($o['order_type']) ?></span></td><td><?= htmlspecialchars($o['status']) ?></td><td><?= htmlspecialchars($o['payment_method']) ?></td><td>R$ <?= number_format((float)$o['total_amount'],2,',','.') ?></td><td><form method="post" action="<?= base_url('/orders/status') ?>" class="d-flex gap-2"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $o['id'] ?>"><select class="form-select form-select-sm" name="status"><option>novo</option><option>em preparo</option><option>pronto</option><option>saiu para entrega</option><option>entregue</option><option>cancelado</option></select><button class="btn btn-sm btn-primary">Atualizar</button><a class="btn btn-sm btn-outline-dark" href="<?= base_url('/orders/print?id=' . $o['id']) ?>" target="_blank">80mm</a></form></td></tr><?php endforeach; ?></tbody></table></div></div>
